@@ -1,11 +1,12 @@
 // Browser-bundle entry (ADR-0090): re-export the Rian compiler's public JS API from the
 // stock-purs JS build (`output-js/`). `esbuild` inlines this + its transitive deps into one ESM
-// artifact the playground loads. `compile` lowers Rian source to an ECMAScript module string;
-// `compileTypes` the `.d.mts` TypeScript declaration sidecar; `compileTs` a native typed `.ts` module.
+// artifact the playground loads.
+//
+// The live engine lowers via the **parse-once** front door (`Rian.Lower.All`): `prepare` runs the
+// shared front-end (lex → Pratt → Core → assemble → tail → type-gate) ONCE and returns an opaque
+// checked program; `lowerJs`/`lowerTs`/`lowerRust`/`lowerJvm` then lower it per target (each may
+// raise its own target-specific rejection — caught per pane). BEAM stays out: `Rian.Beam` needs
+// `:compile.forms`, an Erlang/OTP runtime API with no browser equivalent.
+export { prepare, lowerJs, lowerTs, lowerRust, lowerJvm } from "../output-js/Rian.Lower.All/index.js";
+// One-shot `String -> String` emitters kept for back-compat + the build/bundle smoke checks.
 export { compile, compileTypes, compileTs } from "../output-js/Rian.JS/index.js";
-// The non-JS *source* emitters also run in-browser (they are pure PureScript, no toolchain): the
-// whole-program Rust assembly (`rustProgram`, == the `rs` tour pane's `Rian.Lower.rust_program`) and
-// the Kotlin/JVM emitter (`Rian.JVM.compile`, == the `jvm` pane). Aliased to avoid the `compile`
-// name clash. (BEAM stays out — `Rian.Beam` needs `:compile.forms`, an Erlang/OTP runtime API.)
-export { rustProgram as compileRust } from "../output-js/Rian.Lower.Rust/index.js";
-export { compile as compileJvm } from "../output-js/Rian.JVM/index.js";

@@ -3,11 +3,22 @@
 // tutorial (`pages/by-example.astro`). The compiler is the real Rian → JS
 // compiler, compiled to JS by stock purs and served from `public/`.

+// An opaque, parsed + type-checked program (`Rian.Lower.All.Prepared`) — produced once by
+// `prepare`, then lowered to each target. Callers only thread it through.
+export type Prepared = unknown;
+
 export type Compiler = {
-  compile: (src: string) => string; // the runtime ECMAScript module (.mjs)
-  compileTs: (src: string) => string; // a native, typed TypeScript module (.ts)
-  compileRust: (src: string) => string; // whole-program Rust (== the `rs` tour pane)
-  compileJvm: (src: string) => string; // Kotlin/JVM source (== the `jvm` tour pane)
+  // parse-once front door (ADR-0090): run the shared front-end (lex → parse → Core → type-gate)
+  // a single time; throws on a parse / shared type-gate error (the buffer is invalid everywhere).
+  prepare: (src: string) => Prepared;
+  // per-target lowerings of a prepared program; each may throw its own target-specific rejection.
+  lowerJs: (p: Prepared) => string; // the runtime ECMAScript module (.mjs)
+  lowerTs: (p: Prepared) => string; // a native, typed TypeScript module (.ts)
+  lowerRust: (p: Prepared) => string; // whole-program Rust (== the `rs` tour pane)
+  lowerJvm: (p: Prepared) => string; // Kotlin/JVM source (== the `jvm` tour pane)
+  // one-shot String->String emitters (back-compat; e.g. the build smoke checks).
+  compile: (src: string) => string;
+  compileTs: (src: string) => string;
 };

